class Solution {
public:
    int maximumLength(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> dp(n, vector<int>(k + 1, 1));
        int ans = 1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= k; ++j) {
                for (int p = 0; p < i; ++p) {
                    if (nums[p] == nums[i]) {
                        dp[i][j] = max(dp[i][j], dp[p][j] + 1);
                    } else if (j > 0) {
                        dp[i][j] = max(dp[i][j], dp[p][j - 1] + 1);
                    }
                }
                ans = max(ans, dp[i][j]);
            }
        }
        return ans;
    }
};

class Solution {
    public int maximumLength(int[] nums, int k) {
        int n = nums.length;
        int[][] dp = new int[n][k + 1];
        for (int i = 0; i < n; ++i) Arrays.fill(dp[i], 1);
        int ans = 1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= k; ++j) {
                for (int p = 0; p < i; ++p) {
                    if (nums[p] == nums[i]) {
                        dp[i][j] = Math.max(dp[i][j], dp[p][j] + 1);
                    } else if (j > 0) {
                        dp[i][j] = Math.max(dp[i][j], dp[p][j - 1] + 1);
                    }
                }
                ans = Math.max(ans, dp[i][j]);
            }
        }
        return ans;
    }
}

var maximumLength = function(nums, k) {
    const n = nums.length;
    const dp = Array.from({ length: n }, () => new Array(k + 1).fill(1));
    let ans = 1;
    for (let i = 0; i < n; ++i) {
        for (let j = 0; j <= k; ++j) {
            for (let p = 0; p < i; ++p) {
                if (nums[p] === nums[i]) {
                    dp[i][j] = Math.max(dp[i][j], dp[p][j] + 1);
                } else if (j > 0) {
                    dp[i][j] = Math.max(dp[i][j], dp[p][j - 1] + 1);
                }
            }
            ans = Math.max(ans, dp[i][j]);
        }
    }
    return ans;
};
